using System.Diagnostics;using System.Net;using System.Net.Http.Json;using System.Net.Sockets;using System.Text;using System.Text.Json;using ETulong;using ETulongData;using Microsoft.EntityFrameworkCore;using Npgsql;using Xunit;using Xunit.Abstractions;
[assembly:CollectionBehavior(DisableTestParallelization=true)]
namespace ETulongTests;
public abstract class ApiFixture(ITestOutputHelper output):IAsyncLifetime {
 protected readonly ITestOutputHelper Output=output;protected static readonly DateOnly D=new(2030,1,15);
 protected readonly string Name="etulong_"+Guid.NewGuid().ToString("N")+"_test";protected string Connection="";protected HttpClient Http=null!;protected ReferenceData Reference=null!;protected StringBuilder Log=new();Process? server;string root="";
 string Admin=>Environment.GetEnvironmentVariable("ETULONG_TEST_ADMIN")??"Host=127.0.0.1;Port=55432;Database=postgres;Username=postgres;Pooling=false";
 protected DeskDb Db()=>new(new DbContextOptionsBuilder<DeskDb>().UseNpgsql(Connection).Options);
 public async Task InitializeAsync(){var dir=new DirectoryInfo(AppContext.BaseDirectory);while(dir is not null&&!File.Exists(Path.Combine(dir.FullName,"eTulong.sln")))dir=dir.Parent;root=dir?.FullName??throw new Exception("Run from the extracted project tree.");await using(var c=new NpgsqlConnection(Admin)){await c.OpenAsync();await using var cmd=new NpgsqlCommand($"CREATE DATABASE \"{Name}\"",c);await cmd.ExecuteNonQueryAsync();}Connection=new NpgsqlConnectionStringBuilder(Admin){Database=Name,Pooling=false}.ToString();await using(var db=Db()){await db.Database.MigrateAsync();await Seed.Run(db);}await Start();Reference=(await Call<ReferenceData>("GET","reference",200))!;Output.WriteLine($"Real PostgreSQL {Name}; real Kestrel; fixed date {D}; independent context per operation.");}
 protected async Task Start(bool fault=false){Stop();var l=new TcpListener(IPAddress.Loopback,0);l.Start();var port=((IPEndPoint)l.LocalEndpoint).Port;l.Stop();Http=new HttpClient{BaseAddress=new Uri($"http://127.0.0.1:{port}/"),Timeout=TimeSpan.FromSeconds(15)};var config=AppContext.BaseDirectory.Contains(Path.DirectorySeparatorChar+"Release"+Path.DirectorySeparatorChar)?"Release":"Debug";var dll=Path.Combine(root,"Api","bin",config,"net8.0","Api.dll");var start=new ProcessStartInfo(Environment.GetEnvironmentVariable("ETULONG_DOTNET")??"dotnet"){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};start.ArgumentList.Add(dll);start.Environment["ETULONG_DB"]=Connection;start.Environment["ASPNETCORE_URLS"]=Http.BaseAddress.ToString();start.Environment["ASPNETCORE_ENVIRONMENT"]="Development";start.Environment["ETULONG_TEST_DATE"]=D.ToString("yyyy-MM-dd");start.Environment["ETULONG_FAULT_AFTER_WRITE"]=fault?"1":"0";start.Environment["Logging__LogLevel__Default"]="Warning";server=Process.Start(start)!;server.OutputDataReceived+=(_,a)=>{if(a.Data is not null)lock(Log)Log.AppendLine(a.Data);};server.ErrorDataReceived+=(_,a)=>{if(a.Data is not null)lock(Log)Log.AppendLine(a.Data);};server.BeginOutputReadLine();server.BeginErrorReadLine();for(int i=0;i<100;i++){if(server.HasExited)throw new Exception("API exited: "+Log);try{using var r=await Http.GetAsync("health");if(r.IsSuccessStatusCode){Output.WriteLine("Started actual API process "+server.Id);return;}}catch(HttpRequestException){}await Task.Delay(100);}throw new Exception("API did not become ready: "+Log);}
 void Stop(){Http?.Dispose();if(server is not null){if(!server.HasExited){server.Kill(true);server.WaitForExit(10000);}server.Dispose();server=null;}}
 protected async Task<T?> Call<T>(string method,string route,int expected,object? body=null,int actor=1,bool unchanged=false){var before=await State();using var req=new HttpRequestMessage(new HttpMethod(method),"api/"+route);req.Headers.Add("X-Demo-Staff",actor.ToString());if(body is not null)req.Content=JsonContent.Create(body);using var response=await Http.SendAsync(req);var text=await response.Content.ReadAsStringAsync();Output.WriteLine($"{method} {route} actor={actor} => {(int)response.StatusCode}: {text}");Assert.Equal(expected,(int)response.StatusCode);if(unchanged)Assert.Equal(before,await State());if(expected>=400){using var j=JsonDocument.Parse(text);Assert.False(string.IsNullOrWhiteSpace(j.RootElement.GetProperty("message").GetString()));Assert.DoesNotContain("Npgsql",text);return default;}if(expected==201){Assert.NotNull(response.Headers.Location);Assert.StartsWith("/api/cases/",response.Headers.Location!.ToString());}return JsonSerializer.Deserialize<T>(text,new JsonSerializerOptions(JsonSerializerDefaults.Web));}
 protected Task<CaseDetail?> Action(int id,string action,object? body=null,int expected=200,int actor=1,bool unchanged=false)=>Call<CaseDetail>("POST",$"cases/{id}/{action}",expected,body,actor,unchanged);
 protected static readonly byte[] Png=Convert.FromBase64String("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAwMCAO+aNuoAAAAASUVORK5CYII=");
 protected async Task<CaseDetail> Draft(string suffix,int batch=2,bool attach=true){var c=(await Call<CaseDetail>("POST","cases",201,new DraftInput("DEMO-"+suffix,"Applicant "+suffix,"Demo Barangay",null,batch)))!;if(attach)foreach(var r in c.Requirements)c=(await Action(c.Id,"documents",new DocumentInput(r.Id,r.Name+".png",Png)))!;return c;}
 protected async Task<CaseDetail> Endorsed(string suffix,int batch=1){var c=await Draft(suffix,batch);c=(await Action(c.Id,"submit"))!;foreach(var doc in c.Documents)c=(await Action(c.Id,"review",new ReviewInput(doc.Id,"Accepted","Checked fictional sample")))!;return (await Action(c.Id,"endorse"))!;}
 protected async Task<CaseDetail> Scheduled(string suffix){var c=await Endorsed(suffix);c=(await Action(c.Id,"decision",new DecisionInput(true,"Approved by human official"),actor:2))!;return (await Action(c.Id,"schedule",new ScheduleInput(D)))!;}
 protected async Task<string> State(){await using var d=Db();return JsonSerializer.Serialize(new{cases=await d.Applications.AsNoTracking().OrderBy(x=>x.Id).ToArrayAsync(),batches=await d.Batches.AsNoTracking().OrderBy(x=>x.Id).ToArrayAsync(),applicants=await d.Applicants.AsNoTracking().OrderBy(x=>x.Id).ToArrayAsync(),documents=await d.Documents.AsNoTracking().OrderBy(x=>x.Id).ToArrayAsync(),reservations=await d.Reservations.AsNoTracking().OrderBy(x=>x.Id).ToArrayAsync(),approvals=await d.Approvals.AsNoTracking().OrderBy(x=>x.Id).ToArrayAsync(),verifications=await d.Verifications.AsNoTracking().OrderBy(x=>x.Id).ToArrayAsync()});}
 protected async Task Sql(string sql){await using var c=new NpgsqlConnection(Connection);await c.OpenAsync();await using var cmd=new NpgsqlCommand(sql,c);await cmd.ExecuteNonQueryAsync();}
 public async Task DisposeAsync(){Stop();Output.WriteLine("Final independent PostgreSQL state: "+await State());Output.WriteLine("Server diagnostics: "+Log);NpgsqlConnection.ClearAllPools();Assert.Matches("^etulong_[a-f0-9]{32}_test$",Name);await using var c=new NpgsqlConnection(Admin);await c.OpenAsync();await using var cmd=new NpgsqlCommand($"DROP DATABASE IF EXISTS \"{Name}\" WITH (FORCE)",c);await cmd.ExecuteNonQueryAsync();}
}
